<div class="page-heading invoice-heading"><div><h1><?= e($invoice['invoice_no']) ?> <span class="invoice-status invoice-status-<?= e($invoice['payment_status']) ?>"><?= ucfirst($invoice['payment_status']) ?></span></h1><nav class="job-breadcrumb"><a href="index.php?page=admin">Dashboard</a><span>›</span><a href="index.php?page=admin&amp;section=invoices">Invoices</a><span>›</span><strong><?= e($invoice['invoice_no']) ?></strong></nav></div><div class="invoice-heading-actions"><a class="btn btn-light" href="index.php?page=admin&amp;section=invoices">← Back</a><a class="btn btn-primary" href="index.php?page=admin&amp;section=invoices-thermal&amp;id=<?= (int)$invoice['id'] ?>">Print 80mm</a></div></div>
<div class="invoice-detail-grid"><main>
<section class="admin-panel invoice-detail-card"><div class="invoice-detail-top"><div><small>Invoice Type</small><strong><?= $invoice['invoice_type']==='job_card'?'Job Card Invoice':'Quick Invoice' ?></strong></div><div><small>Invoice Date</small><strong><?= e(date('d M Y',strtotime($invoice['invoice_date']))) ?></strong></div><div><small>Created At</small><strong><?= e(date('d M Y h:i A',strtotime($invoice['created_at']))) ?></strong></div><?php if($invoice['job_card_no']): ?><div><small>Job Card</small><strong><?= e($invoice['job_card_no']) ?></strong></div><?php endif; ?></div><div class="invoice-customer-card"><div><small>Customer</small><strong><?= e($invoice['customer_name']?:'Walk-in Customer') ?></strong><span><?= e($invoice['contact_number']?:'') ?></span></div><div><small>Vehicle</small><strong><?= e($invoice['vehicle_number']?:'No Vehicle') ?></strong><span><?= e(trim(($invoice['make']?:'').' '.($invoice['model']?:''))) ?></span></div></div></section>
<section class="admin-panel invoice-detail-card"><div class="panel-heading"><h2>Invoice Items</h2><span><?= count($invoice['items']) ?> items</span></div><div class="table-responsive"><table class="table admin-table invoice-table"><thead><tr><th>#</th><th>Type</th><th>Description</th><th>Qty</th><th>Unit Price</th><th>Amount</th></tr></thead><tbody><?php foreach($invoice['items'] as $n=>$item): ?><tr><td><?= $n+1 ?></td><td><?= e(ucwords(str_replace('_',' ',$item['item_type']))) ?></td><td><?= e($item['description']) ?><?php if (item_price_reduction($item) > 0): ?><small class="d-block text-muted">List price: Rs. <?= number_format((float)$item['list_unit_price'],2) ?> &middot; Part price reduction: Rs. <?= number_format(item_price_reduction($item),2) ?> (included)</small><?php endif; ?></td><td><?= number_format((float)$item['quantity'],2) ?></td><td>Rs. <?= number_format((float)$item['unit_price'],2) ?></td><td>Rs. <?= number_format((float)$item['line_total'],2) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php if($invoice['notes']): ?><section class="admin-panel invoice-detail-card"><h2>Notes</h2><p><?= nl2br(e($invoice['notes'])) ?></p></section><?php endif; ?>
</main><aside>
<section class="admin-panel invoice-total-card"><h2>Totals</h2><?php $partReductions = array_sum(array_map('item_price_reduction', $invoice['items'])); if ($partReductions > 0): ?><div><span>Part Price Reductions (included)</span><strong>Rs. <?= number_format($partReductions,2) ?></strong></div><?php endif; ?><div><span>Subtotal</span><strong>Rs. <?= number_format((float)$invoice['subtotal'],2) ?></strong></div><div><span>Special Service Charge</span><strong>Rs. <?= number_format((float)$invoice['special_service_charge'],2) ?></strong></div><div><span>Invoice Discount</span><strong>- Rs. <?= number_format((float)$invoice['discount_amount'],2) ?></strong></div><div class="invoice-grand-total"><span>Grand Total</span><strong>Rs. <?= number_format((float)$invoice['total_amount'],2) ?></strong></div><div><span>Paid</span><strong>Rs. <?= number_format((float)$invoice['paid_amount'],2) ?></strong></div><div class="invoice-due"><span>Due</span><strong>Rs. <?= number_format((float)$invoice['balance_amount'],2) ?></strong></div></section>
<?php if((float)$invoice['balance_amount']>0.009): ?><section class="admin-panel invoice-payment-card"><h2>Record Payment</h2><form method="post" action="index.php?page=admin&amp;section=invoices-payment&amp;id=<?= (int)$invoice['id'] ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label class="form-label">Amount Received</label><input class="form-control" type="number" name="amount_received" min="0.01" max="<?= e((string)$invoice['balance_amount']) ?>" step="0.01" required><label class="form-label">Payment Method</label><select class="form-select" name="payment_method"><option value="cash">Cash</option><option value="card">Card</option><option value="bank">Online Transfer</option><option value="cheque">Cheque</option><option value="other">Other</option></select><label class="form-label">Reference</label><input class="form-control" name="payment_reference"><button class="btn btn-primary w-100 mt-3">Save Payment</button></form></section><?php endif; ?>
<section class="admin-panel invoice-payment-card"><h2>Payment History</h2><?php if(!$invoice['payments']): ?><p class="empty-note">No payments recorded.</p><?php else: foreach($invoice['payments'] as $payment): ?><div class="invoice-payment-history"><strong><?= e($payment['payment_no']) ?></strong><span><?= e(payment_method_label($payment['payment_method'])) ?> · <?= e(date('d M Y h:i A',strtotime($payment['payment_date']))) ?></span><b>Rs. <?= number_format((float)$payment['amount_applied'],2) ?></b><a class="btn btn-light btn-sm" href="index.php?page=admin&amp;section=invoices-receipt&amp;id=<?= (int)$payment['id'] ?>">Receipt</a><?php if((float)$payment['change_given']>0): ?><small>Change Rs. <?= number_format((float)$payment['change_given'],2) ?></small><?php endif; ?></div><?php endforeach; endif; ?></section>
</aside></div>
